int logfmt_parse_multi(const char *in, char **keys_out, char **vals_out, size_t *num_pairs) {
    const char *pair = in;
    size_t num = 0;

    while (pair) {
        const char *next_pair = strchr(pair, ' ');
        if (next_pair) {
            *next_pair = '\0';
            next_pair++;
        }

        if (*pair == '\0') break;

        const char *eq = strchr(pair, '=');
        if (!eq) return -1;

        size_t klen = (size_t)(eq - pair);
        size_t vlen = (size_t)(strlen(eq + 1));

        keys_out[num] = malloc(klen + 1);
        vals_out[num] = malloc(vlen + 1);

        if (!keys_out[num] || !vals_out[num]) {
            for (size_t i = 0; i <= num; ++i) {
                free(keys_out[i]);
                free(vals_out[i]);
            }
            return -1;
        }

        strncpy(keys_out[num], pair, klen);
        keys_out[num][klen] = '\0';

        const char *val_start = eq + 1;
        while (*val_start == ' ') val_start++;

        if (*val_start == '"') {
            const char *quote_end = strchr(val_start + 1, '"');
            if (!quote_end) return -1;
            size_t qvlen = (size_t)(quote_end - val_start - 1);
            strncpy(vals_out[num], val_start + 1, qvlen);
            vals_out[num][qvlen] = '\0';
            val_start += qvlen + 2;
        } else {
            const char *val_end = strchr(val_start, ' ');
            if (!val_end) val_end = strchr(val_start, '\0');
            size_t vvlen = (size_t)(val_end - val_start);
            strncpy(vals_out[num], val_start, vvlen);
            vals_out[num][vvlen] = '\0';
            val_start += vvlen;
        }

        pair = next_pair;
        num++;
    }

    *num_pairs = num;
    return 0;
}

